import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String searchTerm = req.getParameter("q");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Missing search parameter");
            return;
        }

        // Sanitize sort column against whitelist
        List<String> allowedSorts = Arrays.asList("name", "email", "created_at", "department");
        if (sortCol == null || !allowedSorts.contains(sortCol)) {
            sortCol = "name";
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);

            // Build query with parameterized search but dynamic department filter
            StringBuilder query = new StringBuilder();
            query.append("SELECT id, name, email, department, created_at FROM users WHERE ");
            query.append("(name ILIKE '%" + searchTerm + "%' OR email ILIKE '%" + searchTerm + "%')");

            if (department != null && !department.isEmpty()) {
                // Department comes from a dropdown, validated client-side
                query.append(" AND department = '" + department + "'");
            }

            query.append(" ORDER BY " + sortCol + " ASC LIMIT 50");

            stmt = conn.createStatement();
            rs = stmt.executeQuery(query.toString());

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("name", rs.getString("name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                user.put("created_at", rs.getString("created_at"));
                results.put(user);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log error details for debugging
            System.err.println("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Bulk search endpoint - accepts JSON body
        StringBuilder body = new StringBuilder();
        try (java.io.BufferedReader reader = req.getReader()) {
            String line;
            while ((line = reader.readLine()) != null) {
                body.append(line);
            }
        }

        JSONObject payload = new JSONObject(body.toString());
        String searchTerm = payload.optString("query", "");

        if (searchTerm.length() > 200) {
            resp.sendError(400, "Query too long");
            return;
        }

        // Delegate to GET handler
        req.setAttribute("__internal_q", searchTerm);
        doGet(req, resp);
    }
}
